export function getSkillsByCategory(category: MedicalSkill["category"]): MedicalSkill[] {
  return MEDICAL_SKILLS_REGISTRY.filter((s) => s.category === category);
}

export function getSkillsBySubcategory(category: MedicalSkill["category"], subcategory: string): MedicalSkill[] {
  return MEDICAL_SKILLS_REGISTRY.filter((s) => s.category === category && s.subcategory === subcategory);
}

export function getAllCategories(): { category: MedicalSkill["category"]; subsections: string[] }[] {
  const cats = new Map<MedicalSkill["category"], Set<string>>();
  MEDICAL_SKILLS_REGISTRY.forEach((s) => {
    if (!cats.has(s.category)) cats.set(s.category, new Set());
    cats.get(s.category)!.add(s.subcategory);
  });
  return Array.from(cats.entries()).map(([category, subsections]) => ({ category, subsections: Array.from(subsections).sort() }));
}

export function getSkillById(id: string): MedicalSkill | undefined {
  return MEDICAL_SKILLS_REGISTRY.find((s) => s.id === id);
}

export function getIntegratedSkills(): MedicalSkill[] {
  return MEDICAL_SKILLS_REGISTRY.filter((s) => s.integrated);
}
